+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.LinkedHashMap;
+import java.util.List;
+import java.util.Locale;
+import java.util.Map;
+import java.util.Set;
+import java.util.stream.Collectors;
+
+/**
+ * Narrows the customer list by name and by status.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ * <ul>
+ *   <li>the name text, split on whitespace, has every term appear as a substring
+ *       of the first name or of the last name; matching ignores case and accents;</li>
+ *   <li>the status set is empty, or contains the customer's status.</li>
+ * </ul>
+ *
+ * @param name     the name text as typed; blank means no name filter
+ * @param statuses the statuses to show; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final String QUERY_NAME = "name";
+    private static final String QUERY_STATUS = "status";
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        Set<CustomerStatus> copy = EnumSet.noneOf(CustomerStatus.class);
+        if (statuses != null) {
+            copy.addAll(statuses);
+        }
+        statuses = Collections.unmodifiableSet(copy);
+    }
+
+    /** Returns {@code true} when {@code customer} satisfies both parts of this filter. */
+    public boolean matches(Customer customer) {
+        return matchesName(customer)
+                && (statuses.isEmpty() || statuses.contains(customer.status()));
+    }
+
+    private boolean matchesName(Customer customer) {
+        List<String> terms = nameTerms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /** The folded terms of {@link #name()}; empty when there is no name text. */
+    private List<String> nameTerms() {
+        return Arrays.stream(fold(name).split("[\\s\\p{Z}]+"))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /** Lower-cases {@code text} and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
+    static String fold(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+
+    /**
+     * Reads a filter from URL query parameters: {@code name} holds the name text and
+     * {@code status} a comma-separated list of {@link CustomerStatus} names. Unknown
+     * status names are ignored.
+     */
+    public static CustomerFilter fromQueryParameters(Map<String, List<String>> parameters) {
+        String name = first(parameters.get(QUERY_NAME));
+        List<String> wanted = Arrays.stream(first(parameters.get(QUERY_STATUS)).split(","))
+                .map(String::trim)
+                .toList();
+        Set<CustomerStatus> statuses = EnumSet.noneOf(CustomerStatus.class);
+        for (CustomerStatus status : CustomerStatus.values()) {
+            if (wanted.contains(status.name())) {
+                statuses.add(status);
+            }
+        }
+        return new CustomerFilter(name, statuses);
+    }
+
+    /**
+     * Writes this filter as URL query parameters, the inverse of
+     * {@link #fromQueryParameters(Map)}. Empty parts are left out; statuses appear in
+     * declaration order.
+     */
+    public Map<String, List<String>> toQueryParameters() {
+        Map<String, List<String>> parameters = new LinkedHashMap<>();
+        if (!name.isBlank()) {
+            parameters.put(QUERY_NAME, List.of(name));
+        }
+        if (!statuses.isEmpty()) {
+            String joined = Arrays.stream(CustomerStatus.values())
+                    .filter(statuses::contains)
+                    .map(CustomerStatus::name)
+                    .collect(Collectors.joining(","));
+            parameters.put(QUERY_STATUS, List.of(joined));
+        }
+        return parameters;
+    }
+
+    private static String first(List<String> values) {
+        return (values == null || values.isEmpty()) ? "" : values.get(0);
+    }
+}
