+                "typing must not query per keystroke, but ran " + queryLog.countQueries().size() + " count queries");
+        assertEquals("/?name=ada%20aal", pathAndQuery(page));
+        assertEquals(historyBefore, historyLength(page), "typing must replace the history entry, not push new ones");
+    }
